tasks.starter:
function capacityMbps(bandwidthHz, snrDb) {
  // Shannon: C = B * log2(1 + S/N), where S/N must be a LINEAR ratio.
  const snr = snrDb;                       // SNR used directly
  const bitsPerHz = Math.log2(1 + snr);
  const bitsPerSec = bandwidthHz * bitsPerHz;
  return Math.round(bitsPerSec / 1e6);
}

