// picks an achievable rate for a radio link
function estimateLinkMbps(bandwidthHz, snrDb) {
  const snrLinear = Math.pow(10, snrDb / 10);
  const shannon = bandwidthHz * Math.log2(1 + snrLinear);
  // real radios reach a fraction of the Shannon bound
  return Math.round(shannon / 1e6);
}

// planner: keep raising modulation order while 'we have capacity'
function pickModulation(bandwidthHz, snrDb) {
  const cap = estimateLinkMbps(bandwidthHz, snrDb);
  if (cap > 900) return '1024-QAM';
  if (cap > 400) return '256-QAM';
  return '64-QAM';
}
